import{_ as n,a0 as a,w as r,s as l,ao as d,I as s,x as o,a1 as p,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Linux有問必答：Linux上如何查看某個進程的線程 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：Linux上如何查看某個進程的線程 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：Linux上如何查看某個進程的線程 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：Linux上如何查看某個進程的線程 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150518 Linux FAQs with Answers--How to view threads of a process on Linux","title":"Linux有問必答：Linux上如何查看某個進程的線程","tag":"201506","desc":""},"relativePath":"201506/20150518 Linux FAQs with Answers--How to view threads of a process on Linux.md","filePath":"[post].md"}'),u={name:"201506/20150518 Linux FAQs with Answers--How to view threads of a process on Linux.md"};function x(m,t,f,h,L,c){const e=a("Link");return r(),l("div",null,[t[13]||(t[13]=d(`<h1 id="linux有問必答-linux上如何查看某個進程的線程" tabindex="-1">Linux有問必答：Linux上如何查看某個進程的線程 <a class="header-anchor" href="#linux有問必答-linux上如何查看某個進程的線程" aria-label="Permalink to “Linux有問必答：Linux上如何查看某個進程的線程”">​</a></h1><blockquote><p><strong>問題</strong>： 我的程序在其內部創建並執行了多個線程，我怎樣才能在該程序創建線程後監控其中單個線程？我想要看到帶有它們名稱的單個線程詳細情況（如，CPU/內存使用率）。</p></blockquote><p>線程是現代操作系統上進行並行執行的一個流行的編程方面的抽象概念。當一個程序內有多個線程被叉分出用以執行多個流時，這些線程就會在它們之間共享特定的資源（如，內存地址空間、打開的文件），以使叉分開銷最小化，並避免大量高成本的IPC（進程間通信）通道。這些功能讓線程在併發執行時成為一個高效的機制。</p><p>在Linux中，程序中創建的線程（也稱為輕量級進程，LWP）會具有和程序的PID相同的“線程組ID”。然後，各個線程會獲得其自身的線程ID（TID）。對於Linux內核調度器而言，線程不過是恰好共享特定資源的標準的進程而已。經典的命令列工具，如ps或top，都可以用來顯示線程級別的信息，只是默認情況下它們顯示進程級別的信息。</p><p>這裏提供了<strong>在Linux上顯示某個進程的線程</strong>的幾種方式。</p><h3 id="方法一-ps" tabindex="-1">方法一：PS <a class="header-anchor" href="#方法一-ps" aria-label="Permalink to “方法一：PS”">​</a></h3><p>在ps命令中，“-T”選項可以開啓線程查看。下面的命令列出了由進程號為&lt;pid&gt;的進程創建的所有線程。</p><pre><code>$ ps -T -p &lt;pid&gt;
</code></pre><p><img src="https://farm8.staticflickr.com/7749/17350561110_94cacfc456_c.jpg" alt=""></p><p>“SID”欄表示線程ID，而“CMD”欄則顯示了線程名稱。</p><h3 id="方法二-top" tabindex="-1">方法二： Top <a class="header-anchor" href="#方法二-top" aria-label="Permalink to “方法二： Top”">​</a></h3><p>top命令可以實時顯示各個線程情況。要在top輸出中開啓線程查看，請調用top命令的“-H”選項，該選項會列出所有Linux線程。在top運行時，你也可以通過按“H”鍵將線程查看模式切換為開或關。</p><pre><code>$ top -H
</code></pre><p><img src="https://farm9.staticflickr.com/8824/17350561070_3dfe447974_c.jpg" alt=""></p><p>要讓top輸出某個特定進程&lt;pid&gt;並檢查該進程內運行的線程狀況：</p><pre><code>$ top -H -p &lt;pid&gt;
</code></pre><p><img src="https://farm8.staticflickr.com/7797/17538002751_c8a3d574d8_c.jpg" alt=""></p><h3 id="方法三-htop" tabindex="-1">方法三： Htop <a class="header-anchor" href="#方法三-htop" aria-label="Permalink to “方法三： Htop”">​</a></h3><p>一個對用户更加友好的方式是，通過htop查看單個進程的線程，它是一個基於ncurses的交互進程查看器。該程序允許你在樹狀視圖中監控單個獨立線程。</p><p>要在htop中啓用線程查看，請開啓htop，然後按<code>&lt;F2&gt;</code>來進入htop的設置菜單。選擇“設置”欄下面的“顯示選項”，然後開啓“樹狀視圖”和“顯示自定義線程名”選項。按<code>&lt;F10&gt;</code>退出設置。</p><p><img src="https://farm6.staticflickr.com/5338/17350364568_59bce22e7b_b.jpg" alt=""></p><p>現在，你就會看到下面這樣單個進程的線程視圖。</p><p><img src="https://farm9.staticflickr.com/8885/17350560930_98952d5350_c.jpg" alt=""></p><hr>`,24)),s("p",null,[t[1]||(t[1]=o("via: ",-1)),p(e,{href:"http://ask.xmodulo.com/view-threads-process-linux.html"},{default:i(()=>[...t[0]||(t[0]=[o("http://ask.xmodulo.com/view-threads-process-linux.html",-1)])]),_:1})]),s("p",null,[t[5]||(t[5]=o("作者：",-1)),p(e,{href:"http://ask.xmodulo.com/author/nanni"},{default:i(()=>[...t[2]||(t[2]=[o("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=o(" 譯者：",-1)),p(e,{href:"https://github.com/GOLinux"},{default:i(()=>[...t[3]||(t[3]=[o("GOLinux",-1)])]),_:1}),t[7]||(t[7]=o(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[4]||(t[4]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=o("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[8]||(t[8]=[o("LCTT",-1)])]),_:1}),t[11]||(t[11]=o(" 原創翻譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...t[9]||(t[9]=[o("Linux中國",-1)])]),_:1}),t[12]||(t[12]=o(" 榮譽推出",-1))])])}const w=n(u,[["render",x]]);export{_ as __pageData,w as default};
